#!/usr/bin/env python3
"""Update the Cilium network policy CRDs chart from an upstream release."""

from __future__ import annotations

import argparse
import os
from pathlib import Path
import re
import shutil
import sys
import tempfile
from typing import Any
from urllib.error import HTTPError, URLError
from urllib.request import urlopen

import yaml


CHART = Path(__file__).resolve().parents[1] / "charts/cilium-network-policy-crds"
GENERATED_HEADER = (
    "# Generated by scripts/update-cilium-network-policy-crds.py; do not edit.\n"
)
SEMVER = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)"
    r"(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)
UPSTREAM_PATH = "pkg/k8s/apis/cilium.io/client/crds/v2"
CRDS = {
    "ciliumnetworkpolicies.yaml": {
        "name": "ciliumnetworkpolicies.cilium.io",
        "kind": "CiliumNetworkPolicy",
        "scope": "Namespaced",
    },
    "ciliumclusterwidenetworkpolicies.yaml": {
        "name": "ciliumclusterwidenetworkpolicies.cilium.io",
        "kind": "CiliumClusterwideNetworkPolicy",
        "scope": "Cluster",
    },
}


class UpdateError(Exception):
    """Expected update failure."""


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--cilium-version", required=True)
    parser.add_argument("--chart-version", required=True)
    return parser.parse_args()


def normalize_version(value: str, option: str) -> str:
    normalized = value[1:] if value.startswith("v") else value
    if not SEMVER.fullmatch(normalized):
        raise UpdateError(f"{option} must be a valid SemVer: {value!r}")
    return normalized


def download_crd(version: str, filename: str) -> bytes:
    url = (
        f"https://raw.githubusercontent.com/cilium/cilium/v{version}/"
        f"{UPSTREAM_PATH}/{filename}"
    )
    try:
        with urlopen(url, timeout=60) as response:
            return response.read()
    except (HTTPError, URLError, TimeoutError) as error:
        raise UpdateError(f"failed to download {url}: {error}") from error


def require_mapping(value: Any, location: str) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise UpdateError(f"{location} must be a YAML mapping")
    return value


def validate_crd(content: bytes, filename: str) -> None:
    try:
        documents = list(yaml.safe_load_all(content))
    except (UnicodeError, yaml.YAMLError) as error:
        raise UpdateError(f"{filename} is invalid YAML: {error}") from error

    if len(documents) != 1:
        raise UpdateError(f"{filename} must contain exactly one YAML document")
    document = require_mapping(documents[0], filename)
    expected = CRDS[filename]

    if document.get("apiVersion") != "apiextensions.k8s.io/v1":
        raise UpdateError(f"unexpected apiVersion in {filename}")
    if document.get("kind") != "CustomResourceDefinition":
        raise UpdateError(f"unexpected resource kind in {filename}")

    metadata = require_mapping(document.get("metadata"), f"{filename} metadata")
    if metadata.get("name") != expected["name"]:
        raise UpdateError(f"unexpected CRD name in {filename}")

    spec = require_mapping(document.get("spec"), f"{filename} spec")
    if spec.get("group") != "cilium.io":
        raise UpdateError(f"unexpected CRD group in {filename}")
    if spec.get("scope") != expected["scope"]:
        raise UpdateError(f"unexpected CRD scope in {filename}")

    names = require_mapping(spec.get("names"), f"{filename} spec.names")
    if names.get("kind") != expected["kind"]:
        raise UpdateError(f"unexpected CRD kind in {filename}")

    versions = spec.get("versions")
    if not isinstance(versions, list) or not versions:
        raise UpdateError(f"{filename} spec.versions must be a non-empty list")
    v2 = [
        version
        for version in versions
        if isinstance(version, dict) and version.get("name") == "v2"
    ]
    storage = [
        version
        for version in versions
        if isinstance(version, dict) and version.get("storage") is True
    ]
    if (
        len(v2) != 1
        or v2[0].get("served") is not True
        or v2[0].get("storage") is not True
    ):
        raise UpdateError(f"{filename} must serve and store v2")
    if storage != v2:
        raise UpdateError(f"{filename} must use only v2 as storage version")


def update_chart_text(chart_text: str, cilium_version: str, chart_version: str) -> str:
    def replace_field(text: str, field: str, value: str) -> str:
        pattern = re.compile(rf"(?m)^{re.escape(field)}:.*$")
        if len(pattern.findall(text)) != 1:
            raise UpdateError(f"Chart.yaml must contain exactly one {field} field")
        return pattern.sub(f'{field}: "{value}"', text)

    chart_text = replace_field(chart_text, "version", chart_version)
    return replace_field(chart_text, "appVersion", cilium_version).rstrip() + "\n"


def install_update(staged_crds: Path, staged_chart: Path) -> None:
    crds = CHART / "crds"
    chart_file = CHART / "Chart.yaml"
    backup_crds = staged_crds.parent / "crds.backup"
    backup_chart = staged_crds.parent / "Chart.yaml.backup"
    had_crds = crds.exists()

    shutil.copy2(chart_file, backup_chart)
    if had_crds:
        os.replace(crds, backup_crds)
    try:
        os.replace(staged_crds, crds)
        os.replace(staged_chart, chart_file)
    except OSError:
        if crds.exists():
            shutil.rmtree(crds)
        if had_crds and backup_crds.exists():
            os.replace(backup_crds, crds)
        os.replace(backup_chart, chart_file)
        raise
    if backup_crds.exists():
        shutil.rmtree(backup_crds)


def main() -> int:
    try:
        args = parse_args()
        cilium_version = normalize_version(args.cilium_version, "--cilium-version")
        chart_version = normalize_version(args.chart_version, "--chart-version")

        downloads = {
            filename: download_crd(cilium_version, filename) for filename in CRDS
        }
        for filename, content in downloads.items():
            validate_crd(content, filename)

        chart_file = CHART / "Chart.yaml"
        chart_text = update_chart_text(
            chart_file.read_text(encoding="utf-8"), cilium_version, chart_version
        )

        with tempfile.TemporaryDirectory(
            prefix="cilium-crds-update-", dir=CHART.parent
        ) as temp:
            temporary = Path(temp)
            staged_crds = temporary / "crds"
            staged_chart = temporary / "Chart.yaml"
            staged_crds.mkdir()
            for filename, content in downloads.items():
                (staged_crds / filename).write_bytes(
                    GENERATED_HEADER.encode("utf-8") + content
                )
            staged_chart.write_text(chart_text, encoding="utf-8")
            yaml.safe_load(staged_chart.read_text(encoding="utf-8"))
            install_update(staged_crds, staged_chart)
    except (UpdateError, OSError, UnicodeError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
